		/** 
		 * Tests creating a new Bank.
		 */
		public void testCreate() throws Throwable {
			LOGGER.info( "\n======== CREATE ======== ");
			LOGGER.info( "-- Attempting to create a Bank");

			StringBuilder msg = new StringBuilder( "-- Failed to create a Bank" );

			try {            
				Bank entity = BankService.getBankInstance().createBank( generateNewEntity() );
				thePrimaryKey = entity.getBankId();
				LOGGER.info( "-- Successfully created a Bank with primary key" + thePrimaryKey );
			}
			catch (Exception e) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests reading a Bank. 
		 */
		public Bank testRead() throws Throwable {
			LOGGER.info( "\n======== READ ======== ");
			LOGGER.info( "-- Reading a previously created Bank" );

			Bank entity = null;
			StringBuilder msg = new StringBuilder( "-- Failed to read Bank with primary key" );
			msg.append( thePrimaryKey );
			
			BankFetchOneSummary fetchOneSummary = new BankFetchOneSummary( thePrimaryKey );

			try {
				entity = BankService.getBankInstance().getBank( fetchOneSummary );

				assertNotNull( entity,msg.toString() );

				LOGGER.info( "-- Successfully found Bank " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
			
			return entity;
		}

		/** 
		 * Tests updating a Bank.
		 */
		public void testUpdate() throws Throwable {
			LOGGER.info( "\n======== UPDATE ======== ");
			LOGGER.info( "-- Attempting to update a Bank." );

			StringBuilder msg = new StringBuilder( "Failed to update a Bank : " );        
			Bank entity = null;

			try {            
				entity = testRead();

				assertNotNull( entity, msg.toString() );

				LOGGER.info( "-- Now updating the created Bank." );

				// for use later on...
				thePrimaryKey = entity.getBankId();

				BankService proxy = BankService.getBankInstance();            
				proxy.updateBank( entity );   

				LOGGER.info( "-- Successfully saved Bank - " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : primarykey = " + thePrimaryKey + " : entity-" +  entity + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests deleting a Bank.
		 */
		public void testDelete() throws Throwable {
			LOGGER.info( "\n======== DELETE ======== ");
			LOGGER.info( "-- Deleting a previously created Bank." );

			try{
			    Bank entity = testRead(); 
				BankService.getBankInstance().delete( entity );

				LOGGER.info( "-- Successfully deleted Bank with primary key " + thePrimaryKey );            
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( "-- Failed to delete Bank with primary key " + thePrimaryKey );

				throw e;
			}
		}

		/**
		 * Tests getting all Banks.
		 */
		public void testGetAll() throws Throwable {    
			LOGGER.info( "======== GETALL ======== ");
			LOGGER.info( "-- Retrieving Collection of Banks:" );

			StringBuilder msg = new StringBuilder( "-- Failed to get all Bank : " );        
			List<Bank> collection  = null;

			try {
				// call the static get method on the BankService
				collection = BankService.getBankInstance().getAllBank();

				if ( collection == null || collection.size() == 0 ) {
					LOGGER.warning( unexpectedErrorMsg );
					LOGGER.warning( msg.toString() + " Empty collection returned."  );
				}
				else {
					// Now print out the values
					Bank entity = null;            
					Iterator<Bank> iter = collection.iterator();
					int index = 1;

					while( iter.hasNext() ) {
						// Retrieve the entity   
						entity = iter.next();

						assertNotNull( entity,"-- null entity in Collection." );
						assertNotNull( entity.getBankId(), "-- entity in Collection has a null primary key" );        

						LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
						index++;
					}
				}
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

